section.sourcecode:
/* アンダーソン・ダーリングのA2検定統計量を計算するルーチン。
 *
 * "Goodness-of-Fit Techniques," R. D'Agostino and M. Stephens,
 * editors, Marcel Dekker, Inc., 1986. の記述に基づいて実装した。
 */

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

/* z ~ Unif(0,1) について、ソート済みのn個の標本
 * z[0] .. z[n-1] の生のA^2検定統計量を返す。
 */
extern double compute_A2(double z[], int n);

/* 検定する分布のパラメーターがデータから推定されていないと
 * 仮定して、A^2検定統計量の値A2に対応する有意水準を返す。
 */
extern double A2_significance(double A2);

/* n個の観測値 x[0] .. x[n-1] を、指定された平均を持つ指数分布に
 * 対して検定したときのA^2有意水準を返す。
 *
 * 副作用: 戻ったとき、x[0..n-1] はソートされている。
 */
extern double exp_A2_known_mean(double x[], int n, double mean);

/* n個の観測値 x[0] .. x[n-1] を、一様分布 [min_val, max_val] に
 * 対して検定したときのA^2有意水準を返す。
 *
 * 副作用: 戻ったとき、x[0..n-1] はソートされている。
 */
extern double unif_A2_known_range(double x[], int n,
                    double min_val, double max_val);

/* 指定された平均を持つ指数分布に従って分布する疑似乱数を返す。
 */
extern double random_exponential(double mean);

/* 倍精度浮動小数点数をソートするためにqsort()が使用する
 * 補助関数。
 */
static int
compare_double(const void *v1, const void *v2)
{
    double d1 = *(double *) v1;
    double d2 = *(double *) v2;

    if (d1 < d2)
        return -1;
    else if (d1 > d2)
        return 1;
    else
        return 0;
}

double
compute_A2(double z[], int n)
{
    int i;
    double sum = 0.0;

    if ( n < 5 )
        /* 値が少なすぎる。 */
        return -1.0;

    /* 値のいずれかが範囲 (0, 1) の外にある場合は、直ちに失敗
     * する（そして、以下のコードで浮動小数点の例外が発生する
     * 可能性を避ける）。
     */
    for (i = 0; i < n; ++i)
        if ( z[i] <= 0.0 || z[i] >= 1.0 )
            return -1.0;

    /* D'AgostinoとStephensの101ページ。 */
    for (i = 1; i <= n; ++i) {
        sum += (2 * i - 1) * log(z[i-1]);
        sum += (2 * n + 1 - 2 * i) * log(1.0 - z[i-1]);
    }
    return -n - (1.0 / n) * sum;
}
double
A2_significance(double A2)
{
    /* D'AgostinoとStephensの105ページ。 */
    if (A2 < 0.0)
        return A2;    /* 不正なA2の値 - それを伝搬する。 */

    /* 改ざんされた可能性のある値を確認する。 */
    if (A2 <= 0.201)
        return 0.99;
    else if (A2 <= 0.240)
        return 0.975;
    else if (A2 <= 0.283)
        return 0.95;
    else if (A2 <= 0.346)
        return 0.90;
    else if (A2 <= 0.399)
        return 0.85;

    /* 次に、一貫しない可能性を確認する。 */
    if (A2 <= 1.248)
        return 0.25;
    else if (A2 <= 1.610)
        return 0.15;
    else if (A2 <= 1.933)
        return 0.10;
    else if (A2 <= 2.492)
        return 0.05;
    else if (A2 <= 3.070)
        return 0.025;
    else if (A2 <= 3.880)
        return 0.01;
    else if (A2 <= 4.500)
        return 0.005;
    else if (A2 <= 6.000)
        return 0.001;
    else
        return 0.0;
}

double
exp_A2_known_mean(double x[], int n, double mean)
{
    int i;
    double A2;

    /* 最初のn個の値をソートする。 */
    qsort(x, n, sizeof(x[0]), compare_double);

    /* それらが指数分布に一致すると仮定して、Unif(0,1)に
     * 変換する。
     */
    for (i = 0; i < n; ++i) {
        x[i] = 1.0 - exp(-x[i] / mean);
    }

    /* 次に、本当に一様であるかどうかを確認するためにA^2検定を行う。 */
    A2 = compute_A2(x, n);
    return A2_significance(A2);
}

double
unif_A2_known_range(double x[], int n, double min_val, double max_val)
{
    int i;
    double A2;
    double range = max_val - min_val;

    /* 最初のn個の値をソートする。 */
    qsort(x, n, sizeof(x[0]), compare_double);

    /* Unif(min_val, max_val) をUnif(0,1)に変換する。 */
    for (i = 0; i < n; ++i)
        x[i] = (x[i] - min_val) / range;

    /* 次に、本当に一様であるかどうかを確認するためにA^2検定を行う。 */
    A2 = compute_A2(x, n);
    return A2_significance(A2);
}

double
random_exponential(double mean)
{
    return -mean * log1p(-drand48());
}
